function p({registerIndicator:d,nulls:f}){d({id:"oa-vwad",name:"Volume Weighted Accumulation/Distribution (VWAD)",category:"Volume",placement:"pane",inputs:[{key:"period",type:"number",label:"Volume Weight Period",default:20,min:1,max:5e3,step:1,tooltip:"Lookback over which each bar volume is measured against the rolling volume total."}],plots:[{key:"vwad",type:"line",title:"VWAD",style:{color:"#ffeb3b",lineWidth:2}}],calc(n,w){const a=Math.max(1,Math.min(5e3,Math.floor(Number(w.period)||20))),r=new Array(a).fill(NaN);let t=0,i=0,u=0;const m=new Array(n.length).fill(NaN);for(let o=0;o<n.length;o++){const e=n[o],s=r[t];Number.isFinite(s)&&(i-=s);const l=Number.isFinite(e.volume)?e.volume:0;i+=l,r[t]=l,t=(t+1)%a;let c=0;if(Number.isFinite(e.high)&&Number.isFinite(e.low)&&Number.isFinite(e.close)){const g=e.close-e.low-(e.high-e.close);c=e.high!==e.low?g/(e.high-e.low):0}const b=i>0?l/i:0,h=l*c*b;Number.isFinite(h)&&(u+=h),m[o]=u}return{vwad:f(m)}}})}export{p as default};
